import {uid,MAX_BYTES,parseImport as parseLegacy,validateInvestigation,copyForImport,mdText,reportMarkdown} from './core.js';
export const kinds=['fact','opinion','prediction','context'];
export const decisions=['','sustain','revise','suspend'];
export const decisionLabels={'':'Ainda não registrada',sustain:'Considerar sustentada pelas evidências disponíveis',revise:'Revisar a afirmação',suspend:'Suspender o julgamento'};
export function newCheck(input=''){const now=new Date().toISOString();return {id:uid(),title:'',input,claim:'',kind:'fact',origin:'local',result:null,decision:'',reason:'',unavailable:[],createdAt:now,updatedAt:now};}
const fail=()=>{throw new Error('Estrutura inválida ou limite excedido no arquivo.');};
function obj(v,keys){if(!v||typeof v!=='object'||Array.isArray(v)||Object.keys(v).length!==keys.length||keys.some(k=>!Object.hasOwn(v,k)))fail();}
function str(v,max=6000){if(typeof v!=='string'||v.length>max)fail();}
function identifier(v){str(v,100);if(!/^[a-zA-Z0-9-]+$/.test(v))fail();}
function instant(v){str(v,40);if(!/^\d{4}-\d{2}-\d{2}T/.test(v)||!Number.isFinite(Date.parse(v)))fail();}
export function validateCheck(v){obj(v,Object.keys(newCheck()));identifier(v.id);for(const k of ['input','claim','reason'])str(v[k]);str(v.title,500);instant(v.createdAt);instant(v.updatedAt);if(!kinds.includes(v.kind)||!decisions.includes(v.decision)||!['local','imported'].includes(v.origin))fail();if(!Array.isArray(v.unavailable)||v.unavailable.length>3)fail();v.unavailable.forEach(identifier);
 if(v.result!==null){const r=v.result;obj(r,['corpusVersion','topic','summary','gap','question','evidence']);for(const k of ['corpusVersion','topic','summary','gap','question'])str(r[k]);if(!Array.isArray(r.evidence)||r.evidence.length>3)fail();const ids=new Set();for(const e of r.evidence){obj(e,['id','sourceId','section','passage','relevance','limitation','source']);identifier(e.id);if(ids.has(e.id))fail();ids.add(e.id);for(const k of ['sourceId','section','passage','relevance','limitation'])str(e[k]);obj(e.source,['id','title','author','url','published','updated','checkedAt']);for(const val of Object.values(e.source))str(val);try{const u=new URL(e.source.url);if(!['https:','http:'].includes(u.protocol)||u.username||u.password)fail();}catch{fail();}}if(v.unavailable.some(id=>!ids.has(id)))fail();}
 return structuredClone(v);
}
export function bundle(checks,investigations=[]){return {format:'contraprova',version:2,exportedAt:new Date().toISOString(),checks:checks.map(validateCheck),investigations:investigations.map(validateInvestigation)};}
export function parseBundle(text){if(new TextEncoder().encode(text).length>MAX_BYTES)throw new Error('O arquivo excede 2 MB.');let v;try{v=JSON.parse(text);}catch{throw new Error('O arquivo não contém JSON válido.');}if(v?.version===1)return {checks:[],investigations:parseLegacy(text)};obj(v,['format','version','exportedAt','checks','investigations']);if(v.format!=='contraprova'||v.version!==2)fail();instant(v.exportedAt);if(!Array.isArray(v.checks)||!Array.isArray(v.investigations)||v.checks.length+v.investigations.length>100||!v.checks.length&&!v.investigations.length)fail();const checks=v.checks.map(validateCheck),investigations=v.investigations.map(validateInvestigation);const ids=new Set();for(const x of [...checks,...investigations]){if(ids.has(x.id))fail();ids.add(x.id);}return {checks,investigations};}
export function copyBundle(b){return {checks:b.checks.map(c=>({...validateCheck(c),id:uid(),origin:'imported'})),investigations:b.investigations.map(copyForImport)};}
export function markdown(c){validateCheck(c);const t=mdText;const parts=[`# ${t(c.title||c.claim||'Rascunho')}`,'Contraprova 0.2 — interpretação humana, sem veredito automático.'+(c.origin==='imported'?' Registro importado: conteúdo não autenticado pelo aplicativo.':''),`## Frase trazida\n\n${t(c.input)}`,`## Afirmação investigada\n\n${t(c.claim)}`];if(c.result){parts.push(`## O que encontramos\n\n${t(c.result.summary)}`,`Acervo local: ${t(c.result.corpusVersion)}. Busca por assunto; não é busca ao vivo na internet. Sínteses editoriais não são citações literais.`);for(const [n,e] of c.result.evidence.entries())parts.push(`## Evidência ${n+1}: ${t(e.source.title)}\n\nInstituição: ${t(e.source.author)}\n\nURL: ${t(e.source.url)}\n\nPublicação: ${t(e.source.published)}; atualização: ${t(e.source.updated||'não informada')}; consulta editorial: ${t(e.source.checkedAt)}\n\nSeção: ${t(e.section)}\n\nParáfrase: ${t(e.passage)}\n\nRelevância: ${t(e.relevance)}\n\nLimite: ${t(e.limitation)}${c.unavailable.includes(e.id)?'\n\nUsuário informou que não conseguiu abrir esta fonte.':''}`);parts.push(`## O que ainda falta saber\n\n${t(c.result.gap)}`);}parts.push(`## Minha decisão\n\n${t(decisionLabels[c.decision])}\n\n${t(c.reason||'Sem justificativa registrada.')}`,`Registros: ${t(c.createdAt)} / ${t(c.updatedAt)}. A decisão não transforma a afirmação em verdade. A eficácia pedagógica ainda precisa ser avaliada.`);return parts.join('\n\n')+'\n';}
export {reportMarkdown};
